import{_ as t,c as s,o,ag as n}from"./chunks/framework.DvvEqxGt.js";const p=JSON.parse('{"title":"One line on phones","description":"","frontmatter":{"title":"One line on phones","feedbackMock":2,"editLink":false,"lastUpdated":false},"headers":[],"relativePath":"feedback-box/2-one-line-on-phones.md","filePath":"feedback-box/2-one-line-on-phones.md"}'),a={name:"feedback-box/2-one-line-on-phones.md"};function r(i,e,h,d,u,l){return o(),s("div",null,e[0]||(e[0]=[n('<h1 id="_2-one-line-on-phones" tabindex="-1">2. One line on phones <a class="header-anchor" href="#_2-one-line-on-phones" aria-label="Permalink to &quot;2. One line on phones&quot;">​</a></h1><p><strong>Mockup.</strong> On a phone the box shrinks to one line with the issue link. Tablets and desktops keep today&#39;s box. A phone here means a screen narrower than 768 pixels, or shorter than 500 pixels, which covers a phone held sideways. The rest of this page is a copy of the start of <a href="/docs-website/mockups/engine/queueing.html">Queueing</a>.</p><p>A queue in OIE is not a structure that holds messages in memory. It is a database query for this connector&#39;s messages that are still waiting. The source queue is the set of source connector messages in RECEIVED status for this server. A destination queue is the set of that destination&#39;s connector messages in QUEUED status. Each queue keeps a small in-memory buffer, 1000 rows by default, filled from that query in message id order. The Queued figure on the Dashboard is the row count in the database, not the size of the buffer.</p><p>Because the queue is the database, nothing is lost when a channel stops, is undeployed, or the server restarts. The rows stay where they are and the buffer is rebuilt the next time the queue starts.</p><h2 id="the-source-queue" tabindex="-1">The source queue <a class="header-anchor" href="#the-source-queue" aria-label="Permalink to &quot;The source queue&quot;">​</a></h2><p>The setting is on the <strong>Source</strong> tab under Source Settings, labelled <strong>Source Queue</strong>, with two options.</p><table tabindex="0"><thead><tr><th>Option</th><th>What happens to a message</th></tr></thead><tbody><tr><td><strong>OFF (Respond after processing)</strong></td><td>The thread that received the message runs the whole channel: preprocessor, source filter and transformer, every destination chain, postprocessor. The sender waits for all of it, and its response can come from any point in that path.</td></tr><tr><td><strong>ON (Respond before processing)</strong></td><td>The engine writes the raw message, responds to the sender at once, and processes the message later on a source queue thread.</td></tr></tbody></table><p>With the queue on, the sender&#39;s response is limited to <strong>None</strong> or <strong>Auto-generate (Before processing)</strong>, because nothing else exists yet when the response goes back. The Administrator restricts the Response list accordingly.</p><p>The number of source queue threads equals <strong>Max Processing Threads</strong>. With more than one, messages leave the queue in id order but are processed at the same time, so order is not preserved. See <a href="/docs-website/mockups/engine/threading_and_ordering.html">Threading and Ordering</a>.</p><p>Recovery of source connector messages left in RECEIVED takes one of two paths, and which one runs depends on whether the source queue is on.</p><p>With the source queue on, the queue picks up the source connector messages still in RECEIVED when it starts, and processes them. This path works wherever a source queue is allowed at all, which includes Raw storage mode. In Development and Production, recovery also handles messages whose destinations never finished and destinations left in PENDING, working through all three kinds in message id order, so a RECEIVED source row older than the last of those is processed by recovery in its turn rather than by the queue.</p><p>With the source queue off, the recovery task reprocesses those rows itself, and only then does the storage mode matter. That path is disabled in Raw and Metadata modes, so it runs in Development and Production only.</p><p><strong>Queue Buffer Size</strong> sets the in-memory buffer for this channel and is enabled only when the queue is on. It defaults to the server setting <strong>Default Queue Buffer Size</strong>, <code>server.queuebuffersize</code>, which is 1000 unless changed. The same default applies to destination queues.</p><h2 id="destination-queues" tabindex="-1">Destination queues <a class="header-anchor" href="#destination-queues" aria-label="Permalink to &quot;Destination queues&quot;">​</a></h2><h3 id="queue-modes" tabindex="-1">Queue modes <a class="header-anchor" href="#queue-modes" aria-label="Permalink to &quot;Queue modes&quot;">​</a></h3><p><strong>Queue Messages</strong> on each destination has three options. An exported channel stores them as two booleans, <code>queueEnabled</code> and <code>sendFirst</code>.</p><table tabindex="0"><thead><tr><th>Option</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Never</strong></td><td>Queueing off. The message is sent on the processing thread. A failure, after any retries, ends in ERROR.</td></tr><tr><td><strong>On Failure</strong></td><td>Try to send on the processing thread first. If that fails, or if the queue already holds messages, the message goes to the queue.</td></tr><tr><td><strong>Always</strong></td><td>The message goes to the queue at once and is sent by a queue thread.</td></tr></tbody></table><p>On Failure attempts a direct send only while the queue is empty, which includes having no message that a queue thread is still sending. Once a backlog exists, every new message goes straight to the back of the queue, so a new message does not jump ahead of older ones.</p><p>With Always, and with On Failure while a backlog exists, the next destination in the same chain runs without waiting for the send, and later destinations in the chain see this destination&#39;s response as QUEUED. The postprocessor usually sees QUEUED too, but not always: the queue works on the same in-memory message, so if a queue thread sends it before the postprocessor runs, the postprocessor sees the real response. The destination&#39;s own response transformer, which runs after the send, is the one script certain to see the real response.</p><h3 id="how-a-failed-send-becomes-queued" tabindex="-1">How a failed send becomes QUEUED <a class="header-anchor" href="#how-a-failed-send-becomes-queued" aria-label="Permalink to &quot;How a failed send becomes QUEUED&quot;">​</a></h3><p>Most destination connectors report a failed send as QUEUED and a successful one as SENT. When queueing is Never, the engine converts a QUEUED result to ERROR. So the same transport failure produces ERROR on a destination whose queueing is Never and QUEUED on one with queueing on.</p><p>A few results are ERROR in every queue mode: a JavaScript Writer script that throws or returns ERROR, a TCP Sender response timeout with <strong>Queue on Response Timeout</strong> set to No, a SOAP fault returned to a Web Service Sender, and an HL7 v2.x response that <strong>Validate Response</strong> finds to be an error or rejected acknowledgement or to carry the wrong message control id.</p>',22)]))}const g=t(a,[["render",r]]);export{p as __pageData,g as default};
